namespace GodTreeXOwais.Infrastructure; public sealed class WorkspaceService{public string Ensure(string root){Directory.CreateDirectory(root);Directory.CreateDirectory(Path.Combine(root,".godtree","runs"));return root;}public IEnumerable<string> Files(string root,int max=500)=>Directory.EnumerateFiles(root,"*",SearchOption.AllDirectories).Where(x=>!x.Contains(Path.DirectorySeparatorChar+".git"+Path.DirectorySeparatorChar)).Take(max);}